import {operationDate,currentTimeZone,setTimeZone,validTimeZone} from './time.mjs';
import {migrateFinanceState,parseBRL,saveAccount,saveBudget,validateFinancialEntry,applyFinancialEntry,createObligation,settleObligation,generateRecurrences,obligationRemaining,obligationStatus,accountBalances,financialSummary,parseFinancialCapture,toCsv,validDate} from './finance.mjs';
import {createRecordPdf,createReceiptPdf,createReportPdf} from './pdf.mjs';
import {initialState,id,money,escapeHtml as esc,DEMO_DATE} from './core.mjs';
export const METHOD_LABELS={pix:'Pix',debit:'Débito',cash:'Dinheiro',boleto:'Boleto',transfer:'Transferência',other:'Outro'};
export function demoFinanceState(){const s=migrateFinanceState(initialState());s.accounts=s.accounts.map(a=>({...a,openingBalanceCents:a.id==='itau'?50000:a.id==='nubank'?100000:50000,openingBalanceDate:'2026-10-01'}));s.records=s.records.map((r,i)=>({...r,accountId:['itau','cash','itau','nubank'][i],paymentMethod:['pix','cash','pix','other'][i]}));s.obligations=[{id:'pay-demo',kind:'payable',title:'Material do projeto',cents:30000,settledCents:0,settlementIds:[],status:'open',dueDate:'2026-10-20',category:'Projetos',accountId:'itau'},{id:'receive-demo',kind:'receivable',title:'Serviço combinado',cents:45000,settledCents:0,settlementIds:[],status:'open',dueDate:'2026-10-25',category:'Trabalho',accountId:'nubank'}];s.budgets=[{id:'budget-demo',month:'2026-10',category:'Casa',cents:50000,accountId:null}];return s;}
const monthEnd=month=>{const [y,m]=month.split('-').map(Number);return new Date(Date.UTC(y,m,0,12)).toISOString().slice(0,10);};
const dateLabel=date=>/^\d{4}-\d{2}-\d{2}$/.test(date||'')?date.split('-').reverse().join('/'):'Não informado';
export function createFinanceUI(ctx){
 const {getState,setState,save,toast,modal,closeModal,render,icon,button,link,badge,section,heading,empty,field,selectField,formFooter,download,getRoute}=ctx;
 const $=s=>document.querySelector(s);let month='2026-10',from=month+'-01',to=monthEnd(month),account='all',recordFilter='all',pending=null;
 const state=()=>getState();const name=accountId=>state().accounts.find(a=>a.id===accountId)?.name||'Sem conta definida';
 const activeAccounts=()=>state().accounts.filter(a=>!a.archived);
 const opts=(selected='',allowAll=false)=>`${allowAll?`<option value="all" ${selected==='all'?'selected':''}>Todas as contas</option>`:'<option value="">Escolha uma conta</option>'}${activeAccounts().map(a=>`<option value="${esc(a.id)}" ${a.id===selected?'selected':''}>${esc(a.name)} · manual</option>`).join('')}`;
 const accountField=(label,key,value='',all=false)=>`<label for="field-${key}">${label}</label><select id="field-${key}" name="${key}" ${all?'':'required'}>${opts(value,all)}</select>`;
 const methods=(selected='pix')=>selectField('Forma de pagamento','paymentMethod',Object.entries(METHOD_LABELS),selected);
 const categories=()=>[...new Set(['Casa','Trabalho','Pessoal','Projetos','Alimentação','Transporte','Outros',...state().records.map(r=>r.category).filter(Boolean)])];
 const categoryField=(value='Outros')=>`${field('Categoria','category',value,'text','required maxlength="80" list="financial-categories"')}<datalist id="financial-categories">${categories().map(c=>`<option value="${esc(c)}"></option>`).join('')}</datalist>`;
 const filters=()=>({accountId:account,from,to});const summary=()=>financialSummary(state(),filters());
 const signed=c=>`${c<0?'− ':''}${money(Math.abs(c))}`;
 const fail=messages=>{const text=Array.isArray(messages)?messages.join(' '):String(messages);const error=$('#form-error');if(error)error.textContent=text;else toast(text);};
 const commit=result=>{if(!result.ok){fail(result.errors||'Não foi possível confirmar.');return false;}setState(result.state);const persisted=save();closeModal();render();toast(result.duplicate?'Essa confirmação já foi registrada.':persisted===false?'Atualizado nesta sessão; o navegador não conseguiu persistir.':(globalThis.mentraProduction?'Confirmação preparada para sincronização.':'Confirmado e salvo somente neste navegador.'));return true;};
 function filterBar(){return `<section class="finance-filters" aria-label="Filtros financeiros"><div><label for="finance-month">Mês de referência</label><input id="finance-month" type="month" value="${month}"></div><div><label for="finance-account">Conta manual</label><select id="finance-account">${opts(account,true)}</select></div><div><label for="finance-from">De</label><input id="finance-from" type="date" value="${from}"></div><div><label for="finance-to">Até</label><input id="finance-to" type="date" value="${to}"></div></section>`;}
 function renderFinance(){const tab=getRoute().split('/')[1]||'visao',s=summary();return heading('MEU DINHEIRO · CONTROLE MANUAL','Clareza para decidir com calma.',(globalThis.mentraProduction?'Contas, compromissos e documentos da sua organização.':'Contas, compromissos e documentos. Tudo com dados de demonstração.'),`<div class="button-row">${button('Importar CSV','csv-open','outline')}${link('Criar recibo ou comprovante','vida/documentos/criar','outline')}${button(`${icon('plus')} Novo lançamento`,'finance-add-entry','primary')}</div>`)+`<nav class="finance-tabs" aria-label="Áreas financeiras">${[['visao','Visão do mês'],['contas','Minhas contas'],['lancamentos','Lançamentos'],['compromissos','Pagar e receber'],['relatorios','Relatórios']].map(([r,t])=>link(t,'dinheiro/'+r,'filter '+(r===tab?'selected':''))).join('')}</nav>${filterBar()}<div class="finance-demo-note">${icon('shield')} Contas informadas manualmente. Sem acesso a bancos, Pix real, Open Finance ou notificações externas.</div>${tab==='contas'?renderAccounts():tab==='lancamentos'?renderEntries(s):tab==='compromissos'?renderObligations(s):tab==='relatorios'?renderReports(s):renderOverview(s)}`;}
 function renderOverview(s){const balances=accountBalances(state(),to).filter(a=>account==='all'||a.id===account),allKnown=balances.length&&balances.every(a=>a.known);return `<div class="balance-grid"><section class="balance-card featured"><span>RESULTADO DO PERÍODO</span><strong>${signed(s.net)}</strong><p>Entradas realizadas − saídas realizadas</p></section><section class="balance-card"><span>ENTRADAS REALIZADAS</span><strong>${money(s.income)}</strong><p>Sem saldo inicial ou transferências</p></section><section class="balance-card"><span>SAÍDAS REALIZADAS</span><strong>${money(s.expense)}</strong><p>Somente valores registrados como pagos</p></section></div><div class="forecast-strip"><div>${icon('wallet')}<p><b>Saldo calculado até ${dateLabel(to)}</b><span>${allKnown?'Saldos iniciais informados + movimentos realizados':'Informe o saldo inicial para conhecer o saldo calculado de cada conta.'}</span></p></div><strong>${allKnown?signed(balances.reduce((n,a)=>n+a.balanceCents,0)):'Não informado'}</strong></div><div class="two-columns"><section class="card"><div class="section-head"><h2>Suas contas, separadas</h2>${link('Ver contas '+icon('arrow'),'dinheiro/contas')}</div>${balances.map(a=>`<div class="account-row"><span class="round-icon">${icon(a.kind==='cash'?'wallet':'business')}</span><div><h3>${esc(a.name)}</h3><p>Manual · ${a.known?`saldo inicial de ${dateLabel(a.openingBalanceDate)}`:'saldo inicial não informado'}</p></div><strong>${a.known?signed(a.balanceCents):'—'}</strong></div>`).join('')}${s.unassignedCents?`<div class="notice subtle">Há lançamentos antigos sem conta definida. Eles aparecem no resultado do período, mas não no saldo das contas. Edite-os para escolher a conta.</div>`:''}</section><aside class="stack"><section class="card tinted"><h2>O que vem pela frente</h2><div class="due-mini"><span>A pagar no período</span><b>${money(s.payableCents)}</b></div><div class="due-mini"><span>A receber no período</span><b>${money(s.receivableCents)}</b></div><p class="small">Compromissos em aberto não alteram o saldo até a baixa. Previsões avulsas: entradas ${money(s.estimatedIncome)}, saídas ${money(s.estimatedExpense)}.</p>${link('Revisar compromissos '+icon('arrow'),'dinheiro/compromissos','outline')}</section></aside></div><div class="two-columns finance-lower">${renderCategories(s)}${renderBudgets()}</div><section class="finance-path-banner"><div><h3>Ainda não tem renda?</h3><p>Você pode organizar os gastos e escolher um pequeno começo.</p></div>${link('Encontrar meu caminho '+icon('arrow'),'projetos/income','outline')}</section>`;}
 function renderAccounts(){return `<div class="section-head"><h2>Contas e dinheiro em mãos</h2>${button(`${icon('plus')} Adicionar conta`,'finance-add-account','outline')}</div><div class="finance-account-grid">${accountBalances(state(),to).map(a=>`<section class="card finance-account-card"><div class="section-head"><span class="round-icon">${icon(a.kind==='cash'?'wallet':'business')}</span>${badge(a.archived?'Arquivada':'Manual')}</div><h2>${esc(a.name)}</h2><span class="small-label">SALDO CALCULADO ATÉ ${dateLabel(to)}</span><strong>${a.known?signed(a.balanceCents):'Não informado'}</strong><p>${a.known?`Saldo inicial: ${signed(a.openingBalanceCents)}, no início de ${dateLabel(a.openingBalanceDate)}.`:'Sem saldo inicial, mostramos os movimentos, sem inventar o saldo disponível.'}</p><p>Movimentos considerados: ${signed(a.movementCents)}.</p>${a.beforeOpeningCents?'<p class="small">Registros anteriores à data inicial estão no histórico, sem serem somados novamente ao saldo.</p>':''}${button('Editar conta '+icon('edit'),'finance-edit-account','outline full',`data-id="${esc(a.id)}"`)}</section>`).join('')}</div><div class="notice">O saldo é calculado a partir do que foi informado aqui. Não é um saldo confirmado pelo banco. Registros anteriores à data do saldo inicial não são somados novamente.</div>`;}
 function recordRows(records){return records.length?records.map(r=>`<article class="record financial-record"><span class="record-icon ${r.type}">${icon(r.type==='income'?'down':r.type==='transfer'?'link':'up')}</span><div><h3>${esc(r.title)}</h3><p>${dateLabel(r.date)} · ${r.type==='transfer'?`${esc(name(r.fromAccountId))} → ${esc(name(r.toAccountId))}`:esc(name(r.accountId))}</p><p>${esc(r.category||'Outros')} · ${METHOD_LABELS[r.paymentMethod]||'Outro'} ${r.status==='estimated'?'<span class="forecast-tag">Previsão</span>':''}${r.obligationId?'<span class="forecast-tag">Baixa vinculada</span>':''}</p></div><strong class="${r.type}">${r.type==='income'?'+ ':r.type==='expense'?'− ':''}${money(r.cents)}</strong>${button(icon('arrow'),'finance-view-entry','icon-button',`data-id="${esc(r.id)}" aria-label="Ver ${esc(r.title)}"`)}</article>`).join(''):empty('Nenhum lançamento neste filtro.','Mude o período ou adicione um exemplo.');}
 function renderEntries(s){const records=s.records.filter(r=>recordFilter==='all'||r.type===recordFilter||r.status===recordFilter);return `<section class="card"><div class="section-head"><h2>Lançamentos do período</h2>${button(`${icon('link')} Transferir entre contas`,'finance-add-transfer','outline small-button')}</div><div class="filter-row">${[['all','Todos'],['income','Entradas'],['expense','Saídas'],['transfer','Transferências'],['estimated','Previsões']].map(([v,t])=>button(t,'finance-filter-record','filter '+(recordFilter===v?'selected':''),`data-filter="${v}"`)).join('')}</div>${recordRows(records)}</section><div class="notice warm">Cartões de crédito, faturas e parcelamento ficam para uma próxima versão. Não registre uma compra parcelada como se o total já tivesse saído da conta.</div>`;}
 function renderObligations(s){const items=state().obligations.filter(o=>(account==='all'||o.accountId===account)&&o.dueDate>=from&&o.dueDate<=to).sort((a,b)=>a.dueDate.localeCompare(b.dueDate));return `<div class="obligation-summary"><section><span>A pagar em aberto</span><strong>${money(s.payableCents)}</strong></section><section><span>A receber em aberto</span><strong>${money(s.receivableCents)}</strong></section></div><section class="card"><div class="section-head"><h2>Compromissos do período</h2><div class="button-row">${button('Gerar recorrências do período','finance-generate-recurrences','outline small-button')}${button(`${icon('plus')} Novo compromisso`,'finance-add-obligation','primary small-button')}</div></div><p class="card-intro">A baixa parcial ou total cria um lançamento realizado uma única vez. Nenhum pagamento ou cobrança é executado pelo registro manual.</p>${items.length?items.map(o=>{const status=obligationStatus(o,operationDate()),remaining=obligationRemaining(o);return`<article class="obligation-row"><div><span class="small-label">${o.kind==='payable'?'A PAGAR':'A RECEBER'} · ${dateLabel(o.dueDate)}</span><h3>${esc(o.title)}</h3><p>${esc(o.category)} · ${o.accountId?esc(name(o.accountId)):'Conta a escolher na baixa'}${o.recurrenceId?' · recorrente':''}</p><div class="progress"><i style="width:${Math.min(100,o.settledCents/o.cents*100)}%"></i></div><small>${money(o.settledCents)} baixados de ${money(o.cents)}</small></div><div class="obligation-actions">${badge(({open:'Em aberto',partial:'Parcial',overdue:globalThis.mentraProduction?'Vencido':'Vencido na demo',settled:'Concluído',cancelled:'Cancelado'})[status])}<strong>${money(remaining)}</strong>${remaining&&status!=='cancelled'?button('Registrar baixa','finance-settle-obligation','outline small-button',`data-id="${esc(o.id)}"`):'<span class="muted small">Baixa concluída</span>'}</div></article>`;}).join(''):empty('Nenhum compromisso neste período.','Cadastre uma conta a pagar ou um valor a receber.')}</section><div class="notice subtle">Recorrências criam compromissos em aberto quando você solicita. Não são parcelas, não fazem pagamentos e não enviam lembretes reais. Limite: 12 meses e 100 ocorrências por geração.</div>`;}
 function renderCategories(s){const max=Math.max(1,...s.categories.map(c=>c.expense));return section('Para onde o dinheiro foi',s.categories.length?s.categories.sort((a,b)=>b.expense-a.expense).map(c=>`<div class="category-row"><div><span>${esc(c.category)}</span><strong>${money(c.expense)}</strong></div><div class="category-bar"><i style="width:${c.expense/max*100}%"></i></div><small>Entradas nesta categoria: ${money(c.income)}</small></div>`).join(''):empty('Sem gastos neste período.','As categorias aparecem quando há registros realizados.'));}
 function renderBudgets(){const s=financialSummary(state(),{month,accountId:account});return section('Orçamento por categoria',`<p class="card-intro">Limites do mês ${month.split('-').reverse().join('/')} · contas indicadas em cada orçamento.</p>${s.budgets.length?s.budgets.map(b=>`<div class="budget-row"><div><h3>${esc(b.category)}</h3><span>${b.accountId?esc(name(b.accountId)):'Todas as contas'}</span></div><strong class="${b.exceeded?'over-budget':''}">${money(b.spentCents)} / ${money(b.cents)}</strong><div class="progress"><i style="width:${Math.min(100,b.percent)}%" class="${b.exceeded?'over':''}"></i></div><small>${b.exceeded?'Acima do limite em '+money(-b.remainingCents):'Restam '+money(b.remainingCents)}</small></div>`).join(''):empty('Um limite que cabe na sua realidade.','Defina um orçamento para acompanhar os gastos por categoria.')}`,button(icon('plus'),'finance-add-budget','icon-button','aria-label="Definir orçamento"'));}
 function renderReports(s){return `<section class="card report-card"><div><span class="round-icon">${icon('down')}</span><h2>Seu controle, pronto para guardar.</h2><p>Relatórios do período e da conta selecionados, com entradas, saídas, transferências identificadas e compromissos em aberto.</p><div class="button-row">${button('Baixar relatório PDF','finance-export-pdf','primary')}${button('Baixar lançamentos CSV','finance-export-csv','outline')}</div><p class="small muted">PDF verdadeiro, gerado neste navegador. CSV em português, separado por ponto e vírgula, com proteção contra fórmulas em textos.</p></div><div class="report-figures"><span>Entradas realizadas <b>${money(s.income)}</b></span><span>Saídas realizadas <b>${money(s.expense)}</b></span><span>Resultado do período <b>${signed(s.net)}</b></span><span>A pagar em aberto <b>${money(s.payableCents)}</b></span><span>A receber em aberto <b>${money(s.receivableCents)}</b></span></div></section><div class="two-columns finance-lower">${renderCategories(s)}${renderBudgets()}</div><div class="notice">O relatório não é extrato bancário nem documento fiscal. Use apenas dados fictícios nesta demonstração.</div>`;}
 function openRecord(item={},message='',captureId=''){if(item.obligationId){toast('Esse lançamento é uma baixa vinculada e não pode ser editado isoladamente.');return;}const type=item.type==='transfer'?'transfer':item.type||'expense';modal(item.id?'Editar lançamento':'Revisar lançamento manual',`<p class="muted">Nada será gravado antes da próxima confirmação.</p>${message?`<div class="notice warm">${esc(message)}</div>`:''}<form id="finance-entry-form" data-id="${esc(item.id||'')}" data-capture="${esc(captureId)}">${field('Descrição','title',item.title||'','text','required maxlength="300"')}${selectField('Tipo de movimento','type',[['expense','Saída'],['income','Entrada'],['transfer','Transferência entre contas']],type)}<div class="form-grid"><div>${field('Valor (R$)','amount',Number.isSafeInteger(item.cents)?(item.cents/100).toFixed(2).replace('.',','):'','text','required inputmode="decimal" placeholder="130,00"')}</div><div>${field('Data','date',item.date||operationDate(),'date','required')}</div></div>${accountField('Conta do lançamento / origem','accountId',item.fromAccountId||item.accountId||'')}<div id="finance-transfer-fields" ${type!=='transfer'?'hidden':''}>${accountField('Conta de destino','toAccountId',item.toAccountId||'')}</div><div class="form-grid"><div>${methods(item.paymentMethod||'pix')}</div><div>${selectField('Situação','status',[['actual','Realizado'],['estimated','Previsão']],item.status||'actual')}</div></div>${categoryField(item.category||'Outros')}<p class="small muted">Cartão de crédito, fatura e parcelas não são suportados. Transferência só pode ser registrada como realizada.</p>${formFooter('Revisar antes de salvar')}</form>`);const target=$('#field-toAccountId');if(target)target.required=type==='transfer';}
 function openAccount(item={}){modal(item.id?'Editar conta manual':'Adicionar conta manual',`<p class="muted">Não pedimos agência, número de conta, senha ou acesso ao banco.</p><form id="finance-account-form" data-id="${esc(item.id||'')}">${field('Nome para identificar','name',item.name||'','text','required maxlength="80" placeholder="Minha conta Itaú"')}${selectField('Tipo','kind',[['bank','Conta bancária manual'],['cash','Carteira / dinheiro']],item.kind||'bank')}${field('Saldo inicial informado (R$), opcional','opening',Number.isSafeInteger(item.openingBalanceCents)?(item.openingBalanceCents/100).toFixed(2).replace('.',','):'','text','inputmode="decimal" placeholder="Em branco = saldo desconhecido"')}${field('Saldo no início deste dia','openingBalanceDate',item.openingBalanceDate||'','date')}<p class="small muted">O saldo inicial é a referência no começo da data. Entradas e saídas a partir desse dia serão somadas; as anteriores ficam somente no histórico.</p>${formFooter('Revisar conta')}</form>`);}
 function openObligation(item={}){modal('Uma conta a pagar ou receber',`<p class="muted">O compromisso fica em aberto. O saldo só muda quando você registra a baixa.</p><form id="finance-obligation-form">${field('Descrição','title',item.title||'','text','required maxlength="300"')}${selectField('Tipo','kind',[['payable','A pagar'],['receivable','A receber']],item.kind||'payable')}<div class="form-grid"><div>${field('Valor total (R$)','amount',Number.isSafeInteger(item.cents)?(item.cents/100).toFixed(2).replace('.',','):'','text','required inputmode="decimal"')}</div><div>${field('Vencimento','dueDate',item.dueDate||operationDate(),'date','required')}</div></div>${accountField('Conta prevista','accountId',item.accountId||(account==='all'?'':account))}${categoryField(item.category||'Outros')}${selectField('Repetição','frequency',[['none','Uma vez'],['weekly','Semanal'],['monthly','Mensal'],['yearly','Anual']],item.recurrence?.frequency||'none')}${field('Última data da recorrência, opcional','until',item.recurrence?.until||item.recurrence?.endDate||'','date')}<p class="small muted">A recorrência repete compromissos; não divide uma compra em parcelas. Gere as próximas ocorrências pelo botão do período.</p>${formFooter('Revisar compromisso')}</form>`);}
 function openSettlement(item,draft={}){modal('Registrar baixa parcial ou total',`<p><strong>${esc(item.title)}</strong><br>Saldo em aberto: ${money(obligationRemaining(item))}</p><form id="finance-settlement-form" data-id="${esc(item.id)}">${field('Valor efetivamente pago ou recebido (R$)','amount',((draft.cents??obligationRemaining(item))/100).toFixed(2).replace('.',','),'text','required inputmode="decimal"')}${accountField('Conta usada','accountId',draft.accountId||item.accountId||'')}${field('Data da baixa','date',draft.date||operationDate(),'date','required')}${methods(draft.paymentMethod||'pix')}<div class="notice subtle">A confirmação cria um lançamento e atualiza o restante em uma única ação. Não realiza pagamento ou cobrança real.</div>${formFooter('Revisar baixa')}</form>`);}
 function openBudget(item={}){modal('Definir orçamento da categoria',`<form id="finance-budget-form">${field('Mês','month',item.month||month,'month','required')}${categoryField(item.category||'Casa')}${field('Limite (R$)','amount',Number.isSafeInteger(item.cents)?(item.cents/100).toFixed(2).replace('.',','):'','text','required inputmode="decimal"')}${accountField('Abrangência','accountId',item.accountId||account,true)}<p class="small muted">Um orçamento com o mesmo mês, categoria e conta será atualizado.</p>${formFooter('Revisar orçamento')}</form>`);}
 function review(kind,draft,details,captureId=''){pending={kind,draft,captureId};modal('Confira antes de confirmar',`<div class="review-details">${details.map(([label,value])=>`<div><span>${esc(label)}</span><strong>${esc(value)}</strong></div>`).join('')}</div><div class="notice subtle">Somente o controle local será atualizado. Nenhum banco, pagamento ou mensagem externa será acionado.</div><p id="form-error" class="form-error" role="alert"></p><div class="modal-actions">${button('Voltar e revisar','finance-back-review','outline')}${button('Confirmar e guardar','finance-confirm-review','primary')}</div>`);}
 function entryDetails(r){return [['Descrição',r.title],['Tipo',r.type==='transfer'?'Transferência interna':r.type==='income'?'Entrada':'Saída'],['Valor',money(r.cents)],['Conta',r.type==='transfer'?`${name(r.fromAccountId)} → ${name(r.toAccountId)}`:name(r.accountId)],['Método',METHOD_LABELS[r.paymentMethod]||'Outro'],['Data',dateLabel(r.date)],['Situação',r.status==='actual'?'Realizado':'Previsão'],['Categoria',r.category||'Outros']];}
 function confirmReview(){if(!pending)return;const p=pending;let result;if(p.kind==='entry')result=applyFinancialEntry(state(),p.draft);else if(p.kind==='account')result=saveAccount(state(),p.draft);else if(p.kind==='obligation')result=createObligation(state(),p.draft);else if(p.kind==='settlement')result=settleObligation(state(),p.draft.obligationId,p.draft);else if(p.kind==='budget')result=saveBudget(state(),p.draft);else if(p.kind==='recurrence')result=generateRecurrences(state(),p.draft.throughDate);else if(p.kind==='receipt')return confirmReceipt(p.draft);
  if(result?.ok&&p.captureId){result.state.inbox=result.state.inbox.map(c=>c.id===p.captureId?{...c,confirmed:true,route:'dinheiro/lancamentos',recordId:result.record?.id}:c);}
  if(result&&commit(result)){pending=null;if(p.kind==='recurrence')toast(`${result.count} novos compromissos criados. Repetir não duplica.`);}
 }
 function viewEntry(recordId){const r=state().records.find(r=>r.id===recordId);if(!r)return;const docs=state().documents.filter(d=>d.recordId===r.id&&!d.trashed);modal('Detalhes do lançamento',`<div class="review-details">${entryDetails(r).map(([l,v])=>`<div><span>${esc(l)}</span><strong>${esc(v)}</strong></div>`).join('')}</div><div class="entry-document-actions">${!r.obligationId?button('Editar e revisar','finance-edit-entry','outline',`data-id="${r.id}"`):'<p class="small muted">Baixa vinculada: não editável isoladamente.</p>'}${button('Anexar comprovante de exemplo','finance-attach-document','outline',`data-id="${r.id}"`)}${r.type==='expense'?button('Criar registro de despesa PDF','finance-record-pdf','outline',`data-id="${r.id}"`):''}${r.type!=='transfer'&&r.status==='actual'?button('Preparar rascunho de recibo','finance-receipt-form','primary',`data-id="${r.id}"`):''}</div><h3 class="finance-document-title">Documentos vinculados (${docs.length})</h3>${docs.length?docs.map(d=>button(`${icon('lock')} ${esc(d.title)}`,'finance-open-document','document-link',`data-id="${d.id}"`)).join(''):'<p class="small muted">Nenhum documento vinculado ainda.</p>'}<div class="notice warm">Recibo será um rascunho para revisar e assinar fora do app. Não é nota fiscal nem assinatura eletrônica.</div>`);}
 const pdfPayload=r=>({...r,accountName:r.type==='transfer'?`${name(r.fromAccountId)} → ${name(r.toAccountId)}`:name(r.accountId),methodLabel:METHOD_LABELS[r.paymentMethod]||'Outro'});
 function saveGeneratedDocument(recordId,kind,payload){const r=state().records.find(r=>r.id===recordId),doc={id:id(),title:kind==='receipt_draft'?`Rascunho de recibo · ${r.title}`:`Registro de despesa · ${r.title}`,category:'Finanças',date:operationDate(),note:kind==='receipt_draft'?'Rascunho sem assinatura. Não fiscal.':'Controle de despesa a partir dos dados informados. Não fiscal.',ext:'PDF',trashed:false,recordId,kind,payload:structuredClone(payload)};const next=structuredClone(state());next.documents.unshift(doc);setState(next);save();return doc;}
 function recordPdf(recordId){const r=state().records.find(r=>r.id===recordId);if(!r||r.type!=='expense')return;const doc=saveGeneratedDocument(r.id,'expense_record',pdfPayload(r));downloadDocument(doc);viewEntry(recordId);toast('PDF criado localmente e vinculado ao lançamento.');}
 function receiptForm(recordId,draft={}){const r=state().records.find(r=>r.id===recordId);if(!r||r.type==='transfer'||r.status!=='actual')return;modal('Preparar rascunho de recibo',`<div class="notice warm">Não é nota fiscal. Será gerado um rascunho com linha de assinatura em branco para quem recebeu. Use nomes fictícios.</div><form id="finance-receipt-form" data-id="${r.id}">${field('Quem pagou','payer',draft.payer||'','text','required maxlength="100" placeholder="Nome fictício de quem pagou"')}${field('Quem recebeu','payee',draft.payee||'','text','required maxlength="100" placeholder="Nome fictício de quem recebeu"')}${field('Referente a','title',draft.title||r.title,'text','required maxlength="200"')}<div class="review-details"><div><span>Valor informado</span><strong>${money(r.cents)}</strong></div><div><span>Data</span><strong>${dateLabel(r.date)}</strong></div></div><p class="small muted">O arquivo não confirma pagamento por conta própria. A assinatura deverá ser obtida fora desta demonstração, quando apropriado.</p>${formFooter('Revisar rascunho')}</form>`);}
 function confirmReceipt(draft){const r=state().records.find(r=>r.id===draft.recordId);if(!r)return;const doc=saveGeneratedDocument(r.id,'receipt_draft',{...pdfPayload(r),payer:draft.payer,payee:draft.payee,title:draft.title});pending=null;closeModal();render();downloadDocument(doc);toast('Rascunho PDF criado. A assinatura continua em branco.');}
 function attachForm(recordId){modal('Anexar comprovante de exemplo',`<p class="muted">O arquivo original será mantido apenas neste navegador, vinculado ao lançamento. Nenhum upload para nuvem é feito.</p><div class="notice warm">Use somente arquivo fictício. O armazenamento local desta demo não protege documentos sensíveis. PDF, PNG ou JPEG: até 500 KB por arquivo e 1,5 MB no total.</div><form id="finance-attachment-form" data-id="${recordId}"><label for="finance-file">Arquivo fictício</label><input id="finance-file" name="file" type="file" accept="application/pdf,image/png,image/jpeg" required>${formFooter('Guardar anexo local')}</form>`);}
 async function attachFile(recordId,file){if(!file){fail('Escolha um arquivo fictício.');return;}const maximum=500*1024,total=state().documents.filter(d=>d.fileData).reduce((n,d)=>n+(d.fileSize||0),0);if(file.size>maximum||total+file.size>1536*1024){fail('Limite excedido: até 500 KB por arquivo e 1,5 MB no total.');return;}const bytes=new Uint8Array(await file.arrayBuffer());const pdf=String.fromCharCode(...bytes.slice(0,5))==='%PDF-',png=bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71,jpeg=bytes[0]===255&&bytes[1]===216&&bytes[2]===255;if(!pdf&&!png&&!jpeg){fail('O conteúdo precisa ser um PDF, PNG ou JPEG válido.');return;}const mime=pdf?'application/pdf':png?'image/png':'image/jpeg';if(!(pdf?/\.pdf$/i:png?/\.png$/i:/\.jpe?g$/i).test(file.name)){fail('O nome e o conteúdo precisam corresponder a PDF, PNG ou JPEG.');return;}let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const hash=globalThis.crypto?.subtle?Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(b=>b.toString(16).padStart(2,'0')).join(''):null;const next=structuredClone(state());next.documents.unshift({id:id(),title:file.name.slice(0,120),category:'Finanças',date:operationDate(),note:'Original anexado localmente. Sem envio para nuvem.',ext:pdf?'PDF':png?'PNG':'JPG',trashed:false,kind:'local_original',recordId,fileData:btoa(binary),fileSize:file.size,mime,sha256:hash});const before=state();setState(next);if(save()===false){setState(before);fail('O navegador não conseguiu armazenar o arquivo. Nada foi anexado.');return;}closeModal();render();viewEntry(recordId);toast('Original preservado e vinculado, somente neste navegador.');}
 function documentBytes(doc){if(doc.fileData)return Uint8Array.from(atob(doc.fileData),c=>c.charCodeAt(0));if(doc.kind==='receipt_draft')return createReceiptPdf(doc.payload);return createRecordPdf(doc.payload);}
 function downloadDocument(doc){download(`${doc.kind==='receipt_draft'?'rascunho-recibo':doc.kind==='expense_record'?'registro-despesa':doc.title.replace(/[^\p{L}\p{N}._ -]/gu,'_')}${doc.fileData?'':'.pdf'}`,documentBytes(doc),doc.mime||'application/pdf');}
 function openDocument(documentId){const doc=state().documents.find(d=>d.id===documentId);if(!doc?.recordId)return false;modal(esc(doc.title),`<p>${esc(doc.note)}</p>${doc.payload?'<p class="small muted">O PDF preserva os dados informados na criação. Edições posteriores no lançamento não alteram este arquivo.</p>':''}<div class="review-details"><div><span>Origem</span><strong>${doc.fileData?'Arquivo original local':doc.kind==='receipt_draft'?'Rascunho sem assinatura':'Registro gerado localmente'}</strong></div><div><span>Vinculado a</span><strong>${esc(state().records.find(r=>r.id===doc.recordId)?.title||'Lançamento')}</strong></div>${doc.fileSize?`<div><span>Tamanho</span><strong>${Math.ceil(doc.fileSize/1024)} KB</strong></div>`:''}</div><div class="entry-document-actions">${button('Baixar arquivo','finance-download-document','primary',`data-id="${doc.id}"`)}${doc.ext==='PDF'?button('Abrir PDF para imprimir','finance-print-document','outline',`data-id="${doc.id}"`):''}${button('Ver lançamento','finance-view-entry','outline',`data-id="${doc.recordId}"`)}</div><div class="notice warm">${doc.kind==='receipt_draft'?'Rascunho, não fiscal. Assinatura em branco; nenhum pagamento ou assinatura é validado automaticamente.':'Dados e arquivos desta demonstração ficam somente neste navegador.'}</div>`);return true;}
 function exportReport(kind){const s=summary(),records=s.records.map(r=>({...pdfPayload(r),accountName:r.type==='transfer'?`${name(r.fromAccountId)} → ${name(r.toAccountId)}`:name(r.accountId)}));if(kind==='pdf')download(`mentra-relatorio-${from}-a-${to}.pdf`,createReportPdf({from,to,accountName:account==='all'?'Todas as contas manuais':name(account),summary:s,records}),'application/pdf');else{const rows=records.map(r=>({'Data':r.date,'Descrição':r.title,'Tipo':r.type==='transfer'?'Transferência interna':r.type==='income'?'Entrada':'Saída','Conta':r.accountName,'Método':r.methodLabel,'Categoria':r.category,'Situação':r.status==='actual'?'Realizado':'Previsão','Valor em reais':(r.cents/100).toFixed(2).replace('.',','),'Compromisso vinculado':r.obligationId||''}));download(`mentra-lancamentos-${from}-a-${to}.csv`,toCsv(rows,['Data','Descrição','Tipo','Conta','Método','Categoria','Situação','Valor em reais','Compromisso vinculado']),'text/csv;charset=utf-8');}toast('Relatório gerado neste navegador.');}
 function handleClick(action,data){if(!action.startsWith('finance-'))return false;
  if(action==='finance-add-entry')openRecord();else if(action==='finance-add-transfer')openRecord({type:'transfer',paymentMethod:'transfer'});else if(action==='finance-edit-entry')openRecord(state().records.find(r=>r.id===data.id));else if(action==='finance-view-entry')viewEntry(data.id);else if(action==='finance-add-account')openAccount();else if(action==='finance-edit-account')openAccount(state().accounts.find(a=>a.id===data.id));else if(action==='finance-add-obligation')openObligation();else if(action==='finance-settle-obligation')openSettlement(state().obligations.find(o=>o.id===data.id));else if(action==='finance-add-budget')openBudget();else if(action==='finance-filter-record'){recordFilter=data.filter;render();}else if(action==='finance-confirm-review')confirmReview();else if(action==='finance-back-review'){const p=pending;if(!p)return true;closeModal();if(p.kind==='entry')openRecord(p.draft,'',p.captureId);else if(p.kind==='account')openAccount(p.draft);else if(p.kind==='settlement')openSettlement(state().obligations.find(o=>o.id===p.draft.obligationId),p.draft);else if(p.kind==='receipt')receiptForm(p.draft.recordId,p.draft);else if(p.kind==='budget')openBudget(p.draft);else if(p.kind==='obligation')openObligation(p.draft);}
  else if(action==='finance-generate-recurrences'){const preview=generateRecurrences(state(),to);if(!preview.ok){toast(preview.errors.join(' '));return true;}review('recurrence',{throughDate:to},[['Até a data',dateLabel(to)],['Novos compromissos',String(preview.count)],['Efeito no saldo','Nenhum, ficam em aberto']]);}
  else if(action==='finance-record-pdf')recordPdf(data.id);else if(action==='finance-receipt-form')receiptForm(data.id);else if(action==='finance-attach-document')attachForm(data.id);else if(action==='finance-open-document')openDocument(data.id);else if(action==='finance-download-document'){const d=state().documents.find(d=>d.id===data.id);if(d)downloadDocument(d);}else if(action==='finance-print-document'){const d=state().documents.find(d=>d.id===data.id);if(d){const url=URL.createObjectURL(new Blob([documentBytes(d)],{type:'application/pdf'}));const popup=window.open(url,'_blank');if(popup)popup.opener=null;else{downloadDocument(d);toast('O navegador bloqueou a nova aba. O PDF foi baixado para você imprimir.');}setTimeout(()=>URL.revokeObjectURL(url),60000);}}
  else if(action==='finance-export-pdf')exportReport('pdf');else if(action==='finance-export-csv')exportReport('csv');return true;
 }
 function handleSubmit(form){if(!form.id.startsWith('finance-'))return false;if(!form.checkValidity()){form.reportValidity();return true;}const f=Object.fromEntries(new FormData(form));
  if(form.id==='finance-entry-form'){const draft={id:form.dataset.id||undefined,title:f.title.trim(),type:f.type,cents:parseBRL(f.amount),date:f.date,category:f.category.trim(),accountId:f.accountId||null,paymentMethod:f.paymentMethod,status:f.status,idempotencyKey:id()};if(draft.type==='transfer'){draft.fromAccountId=f.accountId;draft.toAccountId=f.toAccountId;draft.paymentMethod='transfer';}const result=validateFinancialEntry(state(),draft);if(!result.ok){fail(result.errors);return true;}review('entry',result.draft,entryDetails(result.draft),form.dataset.capture||'');}
  else if(form.id==='finance-account-form'){const amount=f.opening.trim()===''?null:parseBRL(f.opening,{allowZero:true,allowNegative:true});if(f.opening.trim()!==''&&amount===null){fail('Informe um saldo válido, como 500,00, ou deixe em branco.');return true;}const draft={id:form.dataset.id||undefined,name:f.name.trim(),kind:f.kind,openingBalanceCents:amount,openingBalanceDate:f.openingBalanceDate||null,archived:false};const result=saveAccount(state(),draft);if(!result.ok){fail(result.errors);return true;}review('account',draft,[['Conta',draft.name],['Saldo inicial',amount===null?'Não informado':signed(amount)],['Referência no início do dia',dateLabel(draft.openingBalanceDate)],['Origem','Informado manualmente, sem conexão bancária']]);}
  else if(form.id==='finance-obligation-form'){const draft={title:f.title.trim(),kind:f.kind,cents:parseBRL(f.amount),dueDate:f.dueDate,category:f.category.trim(),accountId:f.accountId||null,idempotencyKey:id()};if(f.frequency!=='none')draft.recurrence={frequency:f.frequency,interval:1,...(f.until?{until:f.until}:{})};const result=createObligation(state(),draft);if(!result.ok){fail(result.errors);return true;}review('obligation',draft,[['Descrição',draft.title],['Tipo',draft.kind==='payable'?'A pagar':'A receber'],['Valor',money(draft.cents)],['Vencimento',dateLabel(draft.dueDate)],['Conta',name(draft.accountId)],['Repetição',({none:'Uma vez',weekly:'Semanal',monthly:'Mensal',yearly:'Anual'})[f.frequency]],['Efeito no saldo','Nenhum até registrar uma baixa']]);}
  else if(form.id==='finance-settlement-form'){const draft={obligationId:form.dataset.id,cents:parseBRL(f.amount),accountId:f.accountId,date:f.date,paymentMethod:f.paymentMethod,idempotencyKey:id()};const result=settleObligation(state(),draft.obligationId,draft);if(!result.ok){fail(result.errors);return true;}review('settlement',draft,[['Compromisso',state().obligations.find(o=>o.id===draft.obligationId).title],['Valor desta baixa',money(draft.cents)],['Conta',name(draft.accountId)],['Método',METHOD_LABELS[draft.paymentMethod]],['Data',dateLabel(draft.date)],['Saldo em aberto após baixa',money(obligationRemaining(result.obligation))]]);}
  else if(form.id==='finance-budget-form'){const draft={month:f.month,category:f.category.trim(),cents:parseBRL(f.amount,{allowZero:true}),accountId:f.accountId==='all'?null:f.accountId};const result=saveBudget(state(),draft);if(!result.ok){fail(result.errors);return true;}review('budget',draft,[['Mês',draft.month],['Categoria',draft.category],['Limite',money(draft.cents)],['Abrangência',draft.accountId?name(draft.accountId):'Todas as contas']]);}
  else if(form.id==='finance-receipt-form'){const r=state().records.find(r=>r.id===form.dataset.id);if(!r)return true;const draft={recordId:r.id,payer:f.payer.trim(),payee:f.payee.trim(),title:f.title.trim()};if(!draft.payer||!draft.payee||!draft.title){fail('Preencha quem pagou, quem recebeu e a finalidade.');return true;}review('receipt',draft,[['Documento','Rascunho de recibo de pagamento'],['Quem pagou',draft.payer],['Quem recebeu',draft.payee],['Referente a',draft.title],['Valor',money(r.cents)],['Data',dateLabel(r.date)],['Assinatura','Linha em branco, fora desta demonstração'],['Natureza','Não fiscal; não valida pagamento automaticamente']]);}
  else if(form.id==='finance-attachment-form'){attachFile(form.dataset.id,$('#finance-file')?.files?.[0]).catch(()=>fail('Não foi possível ler ou armazenar o arquivo. Tente um exemplo menor.'));}
  return true;
 }
 function handleChange(event){const el=event.target;if(el.id==='field-type'&&$('#finance-transfer-fields')){$('#finance-transfer-fields').hidden=el.value!=='transfer';$('#field-toAccountId').required=el.value==='transfer';return true;}if(el.id==='finance-account'){account=el.value;render();return true;}if(el.id==='finance-month'){if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(el.value))return true;month=el.value;from=month+'-01';to=monthEnd(month);render();return true;}if(el.id==='finance-from'||el.id==='finance-to'){if(!validDate(el.value)){toast('Escolha uma data válida.');return true;}const nextFrom=el.id==='finance-from'?el.value:from,nextTo=el.id==='finance-to'?el.value:to;if(nextFrom>nextTo){toast('A data inicial não pode vir depois da final.');render();return true;}from=nextFrom;to=nextTo;render();return true;}return false;}
 function capture(text,kind='text',today=operationDate()){if(kind==='file')return null;const parsed=parseFinancialCapture(text,state(),{today});if(parsed.type==='none')return null;return{id:id(),source:kind,type:'record',title:text,confirmed:false,financial:true,draft:parsed.draft||{title:text},cents:parsed.cents??parsed.draft?.cents??null,recordType:parsed.draft?.type||'expense',category:parsed.draft?.category||'Outros',questions:parsed.questions||[],needsClarification:parsed.type==='clarification',suggestedObligationKind:parsed.suggestedObligationKind||null,documentIntent:/recibo|nota|comprovante/i.test(text)};}
 function reviewCapture(c){const msg=[...(c.questions||[]),c.suggestedObligationKind?'Você descreveu um valor futuro. Pode registrar uma previsão ou cadastrar uma conta em Pagar e receber.':'',c.documentIntent?'Você também pode criar um recibo independente em Documentos → Criar recibo ou comprovante. Nenhuma nota fiscal será emitida.':''].filter(Boolean).join(' ');openRecord({...c.draft,title:c.title},msg,c.id);}
 function captureDescription(c){if(c.needsClarification)return 'Precisa de esclarecimento. Revise valor, data, conta e método antes de continuar.';const d=c.draft||{};return `${d.type==='transfer'?'Transferência interna':d.type==='income'?'Entrada':'Saída'} de ${Number.isSafeInteger(d.cents)?money(d.cents):'valor a definir'} · ${d.type==='transfer'?`${name(d.fromAccountId)} → ${name(d.toAccountId)}`:name(d.accountId)} · ${METHOD_LABELS[d.paymentMethod]||'método a revisar'}`;}
 return {renderFinance,handleClick,handleSubmit,handleChange,openRecord,capture,reviewCapture,captureDescription,openDocument,viewEntry,exportReport,cancelPending:()=>{pending=null;}};
}
